let notificationSequence=Date.now();
function actionLabel(path){const parts=path.split('?')[0].split('/');const labels={'updates':'Updates prüfen','update-all':'Erweiterungen aktualisieren','update-extension':'Erweiterung aktualisieren','snapshot':'Sicherung erstellen','restore':'Backup wiederherstellen','delete':'Löschen','runtime':'PHP-Version ändern','check':'Prüfung','install':'Installation','sync':'Katalog abrufen','download':'Herunterladen','credentials':'Zugangsdaten speichern','licenses':'Lizenz speichern','users':'CMS-Benutzer verwalten'};return (labels[parts.at(-1)]||({'projects':'Projekt erstellen','extension-sources':'Erweiterungsquelle speichern','providers':'Anbieter speichern','extensions':'Erweiterungen verwalten'})[parts[0]]||'Aktion ausführen')+(parts[0]==='projects'&&parts[1]?' · '+parts[1]:'');}
function notify(id,title,status,text){const previous=notifications.get(id);if(previous&&previous.title===title&&previous.status===status&&previous.text===text)return;const expiresAt=['queued','running'].includes(status)?null:(previous?.status===status&&previous.expiresAt?previous.expiresAt:Date.now()+(status==='done'?8000:20000));notifications.set(id,{title,status,text,expiresAt});renderToasts();}
function renderToasts(){const box=$('#toasts');if(!box)return;clearTimeout(toastTimer);const now=Date.now();let nextExpiry=Infinity;for(const [id,n] of notifications){if(['queued','running'].includes(n.status)){n.expiresAt=null;continue;}if(!n.expiresAt)n.expiresAt=now+(n.status==='done'?8000:20000);if(n.expiresAt<=now){notifications.delete(id);dismissedJobs.add(id);}else nextExpiry=Math.min(nextExpiry,n.expiresAt);}if(Number.isFinite(nextExpiry))toastTimer=setTimeout(renderToasts,Math.max(1,nextExpiry-now));const present=new Set();for(const [id,n] of notifications){present.add(id);let card=Array.from(box.children).find(x=>x.dataset.notification===id);if(!card){card=el('article',undefined,'toast');card.dataset.notification=id;const title=el('strong'),state=el('span'),text=el('p'),close=el('button','×','toast-close');close.type='button';close.setAttribute('aria-label','Meldung schließen');close.onclick=()=>{notifications.delete(id);dismissedJobs.add(id);renderToasts();};card.append(title,state,text,close);box.append(card);}card.className='toast '+n.status;const [title,state,text]=card.children;if(title.textContent!==n.title)title.textContent=n.title;const statusText=({running:'Läuft …',queued:'Wartet …',done:'Abgeschlossen',error:'Fehler',interrupted:'Unterbrochen'})[n.status]||n.status;if(state.textContent!==statusText)state.textContent=statusText;if(text.textContent!==(n.text||''))text.textContent=n.text||'';}for(const card of Array.from(box.children))if(!present.has(card.dataset.notification))card.remove();try{sessionStorage.setItem('vmm-notifications',JSON.stringify({entries:[...notifications],dismissed:[...dismissedJobs]}));}catch(e){/* Keep notifications usable when browser storage is unavailable. */}}
function syncJobToasts(){for(const j of jobs){if(dismissedJobs.has(j.id))continue;if(notifications.has(j.id)||['queued','running'].includes(j.status))notify(j.id,(jobKinds[j.kind]||j.kind)+' · '+jobResource(j),j.status,j.message);}}
