function renderReleases(){const box=$('#releases');box.replaceChildren();const filter=$('#version-search').value;let found=releases.filter(r=>r.cms===$('#catalog-cms').value&&r.version.includes(filter));found.sort((a,b)=>b.version.localeCompare(a.version,undefined,{numeric:true}));for(const r of found){const row=el('div',undefined,'row');row.append(el('strong',r.cms+' '+r.version));if(packages.some(p=>p.cms===r.cms&&p.version===r.version))row.append(el('span','Archiviert','badge'));else row.append(button('Herunterladen',()=>api('packages/download',{cms:r.cms,version:r.version})));box.append(row);}if(!found.length)empty(box,'Noch keine passenden Versionen. Katalog abrufen oder ein Paket manuell importieren.');}
