 const fromBackup=$('#project-source').value==='backup';$('#project-admin').hidden=fromBackup;$('#project-admin').querySelectorAll('input').forEach(n=>n.disabled=fromBackup);$('#project-cms-label').hidden=fromBackup;$('#project-cms').disabled=fromBackup;$('#project-extension-section').hidden=fromBackup;$('#backup-fields').hidden=!fromBackup;$('#package-label').hidden=fromBackup;select.required=!fromBackup;backup.required=fromBackup;
