const jobKinds={provision:'CMS einrichten','delete-project':'Projekt löschen',start:'Projekt starten',stop:'Projekt stoppen',runtime:'PHP-Laufzeit',snapshot:'Sicherung',extensions:'Erweiterungen installieren','install-extension':'Erweiterung installieren',updates:'Updates prüfen','update-all':'Updates installieren',check:'Versionen prüfen',download:'Download',akeeba:'Akeeba-Import',catalog:'Versionskatalog','environment-check':'Umgebung prüfen','manager-check':'Manager-Updates prüfen','manager-install':'Manager aktualisieren','library-import':'Paket aus Projekt übernehmen','storage-migrate':'Speicherorte umstellen','akeeba-backup':'Akeeba-Backup erstellen'};
function jobResource(j){if(j.resource.startsWith('catalog-'))return cmsLabel(j.resource.slice(8));if(j.resource==='environment'||j.resource==='storage-settings')return 'System';if(j.resource==='manager-update')return 'Website Manager';if(j.resource==='shared-runtime')return 'Gemeinsame Laufzeiten';if(j.resource.startsWith('extension-'))return extensionSources.find(s=>s.id===j.resource.slice(10))?.name||j.resource;return j.resource;}
let activityJobs=[],activityTotal=0,activityOffset=0,activityRequest=0;
function localDateTime(date){return new Date(date.getTime()-date.getTimezoneOffset()*60000).toISOString().slice(0,19);}
function defaultActivityRange(){$('#activity-from').value=localDateTime(new Date(Date.now()-7*86400000));$('#activity-to').value='';activityOffset=0;}
function activityQuery(){const query=new URLSearchParams({history:'1',offset:String(activityOffset),limit:'50'});for(const key of ['from','to']){const value=$('#activity-'+key).value;if(value)query.set(key,String(new Date(value).getTime()/1000));}const search=$('#activity-search').value.trim();if(search){query.set('search',search);for(const [kind,label] of Object.entries(jobKinds))if(label.toLocaleLowerCase('de-DE').includes(search.toLocaleLowerCase('de-DE')))query.append('kind',kind);}const status=$('#activity-status').value;if(status)query.set('status',status);return query;}
async function loadActivity(){const request=++activityRequest;try{const data=await api('jobs?'+activityQuery());if(request!==activityRequest)return;if(activityOffset&&activityOffset>=data.total){activityOffset=Math.max(0,Math.floor((data.total-1)/50)*50);return loadActivity();}activityJobs=data.jobs;activityTotal=data.total;message();renderJobs();}catch(e){if(request===activityRequest){activityJobs=[];activityTotal=0;renderJobs();message(e);}}}
function renderJobs(){const box=$('#jobs'),open=new Set(Array.from(box.querySelectorAll('details[open]')).map(d=>d.dataset.job));box.replaceChildren();const selected=activityJobs;$('#activity-count').textContent=activityTotal+' Vorgänge';$('#activity-page').textContent=activityTotal?(activityOffset+1)+'–'+(activityOffset+selected.length)+' von '+activityTotal:'0 Vorgänge';$('#activity-prev').disabled=activityOffset===0;$('#activity-next').disabled=activityOffset+selected.length>=activityTotal;const active=jobs.filter(j=>['running','queued'].includes(j.status)).length;$('#activity-badge').textContent=active;$('#activity-badge').hidden=!active;if(!selected.length){empty(box,'Keine passenden Vorgänge.');return;}for(const j of selected){const row=el('div',undefined,'activity-entry'),top=el('div',undefined,'activity-entry-heading'),info=el('div');info.append(el('strong',(jobKinds[j.kind]||j.kind)+' · '+jobResource(j)),el('small',new Date(j.created*1000).toLocaleString('de-DE')+(j.finished?' · Dauer '+Math.max(0,j.finished-j.created)+' s':'')));top.append(info,el('span',jobStatuses[j.status]||j.status,'badge '+j.status));const details=el('details');details.dataset.job=j.id;details.open=open.has(j.id);details.append(el('summary','Details anzeigen'),el('pre',j.message||'Keine weitere Meldung.'));row.append(top,details);box.append(row);}}
async function refresh(){if(busy)return;busy=true;try{const [p,a,e,b,j]=await Promise.all([api('projects'),api('packages'),api('extensions'),api('backups'),api('jobs')]);projects=p.projects;phpVersions=p.php;packages=a.packages;releases=a.releases;extensions=e.extensions;licenses=e.licenses;assignments=e.assignments;extensionSources=e.sources||[];providerRecords=e.providers||[];extensionPlans=e.plans||[];backups=b.backups;jobs=j.jobs;syncJobToasts();if(view==='activity')await loadActivity();if(view==='projects'&&!location.hash.split('/')[1])renderProjects();renderJobs();if(view==='projects'){const detail=location.hash.split('/')[1];if(detail){const p=projects.find(p=>p.slug===detail);if(!p&&!jobs.some(j=>j.resource===detail&&['queued','running'].includes(j.status)))location.hash='#projects';else if(projectTab==='overview'&&!$('#project-view input:focus, #project-view select:focus')&&projectSnapshot!==projectState(detail))renderProject(detail);else renderProjectJobs(detail);}}if(view==='versions')renderPackages();if(view==='extensions'&&!$('#extensions input:focus')&&!$('#extensions select:focus')&&!$('#licenses:focus-within'))renderExtensions();if(view==='backups')await renderBackups();if(storageApplying&&view!=='system')await renderStorage();if(view==='system'){await renderRuntimes();await renderManagerUpdate();await loadKickstart();await renderEnvironment();await renderStorage();}}catch(e){message(storageApplying?'Speicherorte werden umgestellt. Verbindung wird automatisch wiederhergestellt …':updateInstalling?'Manager wird aktualisiert. Verbindung wird automatisch wiederhergestellt …':e);}finally{busy=false;}}
function openCreate(){loadKickstart().catch(message);$('#project-form').elements.admin_password.value=generatePassword();const php=$('#project-php');php.replaceChildren();option(php,'auto','Automatisch nach CMS und Erweiterungen');phpVersions.forEach(v=>option(php,v,'PHP '+v));php.value='auto';loadDatabaseProfiles().catch(message);fillProjectSources();renderProjectExtensions();$('#create').showModal();}
$('#new').onclick=openCreate;$('#cancel').onclick=()=>$('#create').close();$('#assign-cancel').onclick=()=>$('#assign').close();$('#detail-close').onclick=()=>$('#detail').close();
$('#project-cms').onchange=()=>{fillProjectSources();renderProjectExtensions();};$('#project-source').onchange=fillProjectSources;$('#search').oninput=renderProjects;$('#catalog-cms').onchange=renderReleases;$('#version-search').oninput=renderReleases;
$('#project-form').onsubmit=e=>{e.preventDefault();act(async()=>{const body=Object.fromEntries(new FormData(e.target));body.prepare=true;if($('#auto-install').checked&&body.source!=='backup')body.admin={name:body.admin_name,username:body.admin_username,email:body.admin_email,password:body.admin_password};body.extensions=Array.from(document.querySelectorAll('#project-extensions input:checked')).map(c=>({source:c.dataset.source,license:document.querySelector('[data-license="'+c.dataset.source+'"]').value,version:document.querySelector('[data-version="'+c.dataset.source+'"]').value}));if(body.source==='backup'){delete body.cms;delete body.admin;body.extensions=[];const [id,...parts]=body.backup.split('/');body.backup_id=id;body.archive=parts.join('/');}const created=await api('projects',body);$('#create').close();location.hash='#projects/'+created.slug;e.target.reset();});};
$('#sync').onclick=()=>act(()=>api('catalog/sync',{cms:$('#catalog-cms').value}));
async function upload(path,file){const id='upload-'+(++notificationSequence);notify(id,'Hochladen · '+file.name,'running','Datei wird übertragen …');try{const r=await fetch('/api/uploads/'+path,{method:'POST',headers:{'X-VMM-Request':'1','X-VMM-Filename':encodeURIComponent(file.name),'Content-Type':'application/octet-stream'},body:file});const data=await r.json();if(!r.ok)throw Error(data.error);notify(id,'Hochladen · '+file.name,'done','Datei gespeichert.');return data;}catch(e){notify(id,'Hochladen · '+file.name,'error',e.message);throw e;}}

function uploadForm(id,path){$(id).onsubmit=e=>{e.preventDefault();act(async()=>{const data=new FormData(e.target),file=data.get('file');data.delete('file');const q=new URLSearchParams(data);message('Datei wird hochgeladen …');await upload(path+'?'+q,file);e.target.reset();message('Gespeichert.');});};}
