$('#backup-form').onsubmit=e=>{e.preventDefault();act(async()=>{const files=Array.from(e.target.elements.files.files),bytes=crypto.getRandomValues(new Uint8Array(12)),id=Array.from(bytes,x=>x.toString(16).padStart(2,'0')).join('');for(let i=0;i<files.length;i++){message('Backup-Datei '+(i+1)+' von '+files.length+' wird hochgeladen …');await upload('backups/'+id,files[i]);}e.target.reset();message('Backup-Dateien gespeichert. Jetzt ein neues Projekt daraus erstellen.');});};
