document.querySelectorAll('[data-tab-group]').forEach(list=>{const buttons=Array.from(list.querySelectorAll('[role="tab"]'));buttons.forEach((b,i)=>{b.onclick=()=>{const hash='#'+list.dataset.tabGroup+'/'+b.dataset.tab;if(location.hash===hash)activateTab(list.dataset.tabGroup,b.dataset.tab);else location.hash=hash;};b.onkeydown=e=>{let index;if(e.key==='ArrowRight')index=(i+1)%buttons.length;else if(e.key==='ArrowLeft')index=(i+buttons.length-1)%buttons.length;else if(e.key==='Home')index=0;else if(e.key==='End')index=buttons.length-1;else return;e.preventDefault();buttons[index].focus();buttons[index].click();};});});
