let credentialProject='',credentialEntries=[];
async function openCredentials(name){credentialProject=name;$('#credentials-title').textContent='Zugangsdaten · '+name;$('#credential-form').hidden=true;await loadCredentials();$('#credentials').showModal();}
async function loadCredentials(){credentialEntries=(await api('projects/'+credentialProject+'/credentials')).credentials;renderCredentials();}
function renderCredentials(){
 const box=$('#credential-list');box.replaceChildren();
 for(const entry of credentialEntries){
  const item=el('div',undefined,'credential-entry');item.append(el('strong',entry.label+(entry.archived?' · Archiviert':'')));
  for(const [key,label] of [['username','Benutzername / E-Mail'],['password','Passwort'],['url','Anmelde-URL'],['note','Notiz']])if(entry[key]){const field=el('label',label);field.append(copyField(entry[key],label+' · '+entry.label));item.append(field);}
  if(entry.url){const a=el('a','Anmeldung öffnen ↗');a.href=entry.url;a.target='_blank';a.rel='noopener noreferrer';item.append(a);}
  const controls=el('div',undefined,'inline');
  if(!entry.archived)controls.append(button('Bearbeiten',()=>editCredential(entry)),button('Archivieren',async()=>{await api('projects/'+credentialProject+'/credentials',{action:'archive',id:entry.id});await loadCredentials();}));
  else controls.append(button('Wiederherstellen',async()=>{await api('projects/'+credentialProject+'/credentials',{action:'restore',id:entry.id});await loadCredentials();}));
  item.append(controls);box.append(item);
 }
 if(!credentialEntries.length)empty(box,'Noch keine Zugangsdaten hinterlegt.');
}
function editCredential(entry){const f=$('#credential-form');f.reset();f.dataset.id=entry?entry.id:'';for(const key of ['label','username','password','url','note'])f.elements[key].value=entry?entry[key]:'';f.elements.password.placeholder='';$('#credential-form-title').textContent=entry?'Zugang bearbeiten':'Zugang hinzufügen';f.hidden=false;}
$('#credential-new').onclick=()=>editCredential(null);
$('#credential-cancel').onclick=()=>{$('#credential-form').reset();$('#credential-form').hidden=true;};
$('#credentials-close').onclick=()=>$('#credentials').close();
$('#credentials').addEventListener('close',()=>{$('#credential-list').replaceChildren();$('#credential-form').reset();credentialEntries=[];credentialProject='';});
$('#credential-form').onsubmit=e=>{e.preventDefault();act(async()=>{const f=e.target;const body=Object.fromEntries(new FormData(f));if(f.dataset.id){body.id=f.dataset.id;}if(f.elements.clear_password.checked)body.password='';delete body.clear_password;await api('projects/'+credentialProject+'/credentials',body);f.reset();f.hidden=true;await loadCredentials();});};

