function generatePassword(){const bytes=crypto.getRandomValues(new Uint8Array(24));const chars='ABCDEFGHJKLMNPQRSTUVWXYZabcdefghijkmnopqrstuvwxyz23456789!@$%';return Array.from(bytes,b=>chars[b%chars.length]).join('');}
