let updateInstalling=false,updatePolling=false;
function renderUpdateProgress(state){const box=$('#manager-update-progress');if(!state){box.hidden=true;return;}box.hidden=false;updateInstalling=['queued','running'].includes(state.status);$('#manager-update-step').textContent=state.message||'Update wird vorbereitet …';$('#manager-update-running').hidden=!updateInstalling;$('#manager-update-heartbeat').textContent=state.time?'Letzte Rückmeldung: '+new Date(state.time*1000).toLocaleString('de-DE'):'';$('#manager-update-connection').textContent=state.waiting?'Seit über 90 Sekunden keine neue Rückmeldung. Mit „Updatehelfer prüfen“ kannst du den Zustand und Docker-Ausgaben abrufen.':'';const log=$('#manager-update-log'),text=state.log||'Noch keine Docker-Ausgaben. Der aktuelle Vorbereitungsschritt steht oben.';if(log.textContent!==text){const atEnd=log.scrollHeight-log.scrollTop-log.clientHeight<30;log.textContent=text;if(atEnd)log.scrollTop=log.scrollHeight;}if(state.diagnostics){$('#manager-update-diagnostics').hidden=false;$('#manager-update-diagnostics').textContent=state.diagnostics;}box.dataset.state=state.status;}
$('#manager-diagnostics').onclick=async()=>{const button=$('#manager-diagnostics');button.disabled=true;try{const data=await api('manager-update/diagnostics');renderUpdateProgress(data.installation);const log=$('#manager-update-diagnostics');log.hidden=false;log.textContent=data.diagnostics;await renderManagerUpdate();}catch(e){$('#manager-update-connection').textContent=e.message;}finally{button.disabled=false;}};
setInterval(async()=>{if(!updateInstalling||updatePolling)return;updatePolling=true;try{await renderManagerUpdate();}catch(e){$('#manager-update-connection').textContent='Verbindung zum Manager unterbrochen. Die Anzeige verbindet sich automatisch wieder; die letzten Ausgaben bleiben erhalten.';}finally{updatePolling=false;}},2000);

async function renderManagerUpdate(){const data=await api('manager-update');renderUpdateProgress(data.installation);const box=$('#manager-update'),notice=$('#update-notice');const {installation:progressState,...releaseState}=data;if(unchanged(box,[releaseState,progressState?.status,progressState?.message,jobActive('manager-update')]))return;box.replaceChildren(el('p','Installierte Version: '+data.current),projectLink(data.source,'GitHub-Releases ↗'));if(data.checked)box.append(el('p','Letzte Prüfung: '+new Date(data.checked*1000).toLocaleString('de-DE')));if(data.error)box.append(el('p',data.error,'small-note'));const installation=data.installation;updateInstalling=installation&&['queued','running'].includes(installation.status);if(installation)box.append(el('p',installation.message,installation.status==='error'?'error':'small-note'));if(data.available&&!data.error){const install=button(updateInstalling?'Update läuft …':'Update '+data.latest+' installieren',async()=>{await api('manager-update/install',{version:data.latest});message('Update gestartet. Der Manager startet neu und verbindet sich anschließend automatisch.');updateInstalling=true;});install.disabled=updateInstalling||jobActive('manager-update');box.append(install);notice.hidden=false;notice.replaceChildren(el('span','Manager-Update '+data.latest+' verfügbar. '));const link=el('a','Update öffnen');link.href='#system/updates';notice.append(link);}else notice.hidden=true;}
