const backupProfiles=new Map();
function renderAkeebaBackups(p,panel){const section=el('section',undefined,'akeeba-backup-section');section.append(el('h2','Akeeba-Backups'));const description=el('p','Echte JPA-Sicherung mit der Akeeba-Installation dieser Website. Die Profil-Einstellungen werden für den lokalen Download vorübergehend übersteuert.');section.append(description);const controls=el('div',undefined,'extra-actions'),label=el('label','Akeeba-Profilnummer'),profile=el('input');profile.type='number';profile.min='1';profile.max='99999';profile.value=backupProfiles.get(p.slug)||'1';profile.oninput=()=>backupProfiles.set(p.slug,profile.value);label.append(profile);const create=button('Akeeba-Backup erstellen',()=>api('projects/'+p.slug+'/akeeba-backup',{profile:Number(profile.value)}),'primary');create.disabled=true;controls.append(label,create);section.append(controls);const list=el('div');list.id='project-akeeba-backups';section.append(list);panel.append(section);api('projects/'+p.slug+'/akeeba-backups').then(data=>{if(!section.isConnected)return;create.disabled=!data.capability.available||jobActive(p.slug)||p.status!=='running'||!!p.restore;if(!data.capability.available)section.insertBefore(el('p',data.capability.reason,'small-note'),list);else if(p.status!=='running')section.insertBefore(el('p','Projekt zuerst starten.','small-note'),list);for(const backup of data.backups){const row=el('div',undefined,'row'),info=el('div');info.append(el('strong',new Date(backup.created*1000).toLocaleString('de-DE')),el('small',backup.status==='complete'?'Profil '+backup.profile+' · '+backup.files.length+' Archivteile':'Sicherung fehlgeschlagen · unvollständige Dateien'));row.append(info);const links=el('div',undefined,'extra-actions');if(backup.status==='complete'){if(backup.files.length>1){const bundle=el('a','Alle Teile als Downloadpaket (.zip)');bundle.href='/api/backup-bundles/'+backup.id+'.zip';bundle.download='akeeba-'+backup.id+'.zip';links.append(bundle);}for(const file of backup.files){const a=el('a',file.name+' · '+formatBytes(file.size));a.href='/api/backups/'+backup.id+'/'+encodeURIComponent(file.name);a.download=file.name;links.append(a);}}else links.append(button('Unvollständiges Backup löschen',async()=>{if(confirm('Unvollständige Akeeba-Sicherung endgültig löschen?'))await api('backups/'+backup.id+'/delete',{});},'danger'));row.append(links);list.append(row);}if(data.backups.some(b=>b.files.length>1))list.append(el('p','Ein Downloadpaket enthält die JPA-Datei und Teilarchive. Vor der Wiederherstellung das Downloadpaket entpacken und alle Archivteile gemeinsam verwenden.','small-note'));if(!data.backups.length)empty(list,'Noch keine Akeeba-Sicherung mit dem Manager erstellt.');}).catch(e=>{if(list.isConnected)list.textContent=e.message;});}
