function storagePaths(){return Object.fromEntries(storageAreas.map(area=>[area.key,$('#storage-form').elements[area.key].value.trim()]));}
function invalidateStorageCheck(){storageChecked='';$('#storage-apply').disabled=true;$('#storage-check-result').replaceChildren();}
async function renderStorage(){const data=await api('storage'),box=$('#storage-areas');storageAreas=data.areas;const finished=data.migration&&['done','error'].includes(data.migration.status)&&data.migration.id!==storageMigrationFinished;if(!box.children.length||finished){box.replaceChildren();for(const area of data.areas){const row=el('div',undefined,'storage-area'),label=el('label',area.label),input=el('input');input.name=area.key;input.value=area.path;input.required=true;input.autocomplete='off';input.oninput=invalidateStorageCheck;label.append(input);const note=el('small',undefined,'small-note');note.dataset.storageUsage=area.key;row.append(label,note);box.append(row);}invalidateStorageCheck();if(finished)storageMigrationFinished=data.migration.id;}for(const area of data.areas)box.querySelector('[data-storage-usage="'+area.key+'"]').textContent='Belegt: '+formatBytes(area.used)+' · Frei: '+formatBytes(area.free);$('#storage-database-note').textContent=data.database;const migration=data.migration;storageApplying=!!migration&&['queued','running'].includes(migration.status);$('#storage-status').textContent=migration?.message||'';$('#storage-form').querySelectorAll('input,button').forEach(input=>{input.disabled=storageApplying;});$('#storage-apply').disabled=storageApplying||!storageChecked;if(migration&&!dismissedJobs.has(migration.id)&&(notifications.has(migration.id)||storageApplying))notify(migration.id,'Speicherorte umstellen',migration.status,migration.message);}
$('#storage-form').onsubmit=e=>{e.preventDefault();act(async()=>{const paths=storagePaths(),result=await api('storage/check',{paths});if(JSON.stringify(paths)!==JSON.stringify(storagePaths()))return;storageChecked=JSON.stringify(paths);$('#storage-check-result').textContent=result.message;$('#storage-apply').disabled=false;});};
$('#storage-reset').onclick=()=>{for(const area of storageAreas)$('#storage-form').elements[area.key].value=area.default;invalidateStorageCheck();};
$('#storage-apply').onclick=()=>act(async()=>{const paths=storagePaths();if(storageChecked!==JSON.stringify(paths))throw Error('Die geänderten Speicherorte zuerst prüfen.');await api('storage/apply',{paths});storageApplying=true;$('#storage-apply').disabled=true;});
